def fact(x):
    if x==0:
        return 1
    else:
        return x*fact(x-1)

def neper():
    s1=1
    s2=2
    i=2
    while abs(s2-s1)>0.0001:
        s1=s2
        s2=s1+1/fact(i)
        i=i+1
    return s2
#Programme appelant
print("La valeur approché de point fixe avec la formule de neper est: ",neper())

